.version 8.0
.target sm_89
.address_size 64

.visible .entry layernorm_kernel(
    .param .u64 x_ptr,
    .param .u64 y_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .u64 n_elems,
    .param .f32 eps
)
{
    .reg .pred %p<8>;
    .reg .b32 %r<16>;
    .reg .b64 %rd<32>;
    .reg .f32 %f<32>;

    .shared .align 4 .f32 sh_sum;
    .shared .align 4 .f32 sh_sq;
    .shared .align 4 .f32 sh_mean;
    .shared .align 4 .f32 sh_rstd;

    ld.param.u64 %rd1, [x_ptr];
    ld.param.u64 %rd2, [y_ptr];
    ld.param.u64 %rd3, [w_ptr];
    ld.param.u64 %rd4, [b_ptr];
    ld.param.u64 %rd5, [n_elems];
    ld.param.f32 %f1, [eps];

    mov.u32 %r1, %ctaid.x;
    mov.u32 %r2, %tid.x;
    mov.u32 %r3, %ntid.x;

    cvt.u64.u32 %rd6, %r1;
    cvt.u64.u32 %rd7, %r2;
    cvt.u64.u32 %rd8, %r3;

    mul.lo.u64 %rd9, %rd6, %rd5;
    mul.lo.u64 %rd10, %rd9, 4;

    add.u64 %rd11, %rd1, %rd10;
    add.u64 %rd12, %rd2, %rd10;
    mov.u64 %rd13, %rd3;
    mov.u64 %rd14, %rd4;

    setp.eq.u32 %p1, %r2, 0;
    mov.f32 %f2, 0f00000000;
    @%p1 st.shared.f32 [sh_sum], %f2;
    @%p1 st.shared.f32 [sh_sq], %f2;
    bar.sync 0;

    mov.u64 %rd15, %rd7;
    mov.f32 %f3, 0f00000000;
    mov.f32 %f4, 0f00000000;

