    setp.ge.u64 %p2, %rd15, %rd5;
    @%p2 bra L_SUM_DONE;

    mul.lo.u64 %rd16, %rd15, 4;
    add.u64 %rd17, %rd11, %rd16;
    ld.global.f32 %f5, [%rd17];

    add.f32 %f3, %f3, %f5;
    mul.f32 %f6, %f5, %f5;
    add.f32 %f4, %f4, %f6;

    add.u64 %rd15, %rd15, %rd8;
