    ld.shared.f32 %f10, [sh_sq];
    cvt.rn.f32.u64 %f11, %rd5;
    div.rn.f32 %f12, %f9, %f11;
    div.rn.f32 %f13, %f10, %f11;
    mul.f32 %f14, %f12, %f12;
    sub.f32 %f15, %f13, %f14;
    mov.f32 %f16, 0f00000000;
