    @%p3 bra L_OUT_DONE;

    mul.lo.u64 %rd19, %rd18, 4;
    add.u64 %rd20, %rd11, %rd19;
    add.u64 %rd21, %rd12, %rd19;
    add.u64 %rd22, %rd13, %rd19;
    add.u64 %rd23, %rd14, %rd19;

    ld.global.f32 %f21, [%rd20];
    ld.global.f32 %f22, [%rd22];
    ld.global.f32 %f23, [%rd23];

    sub.f32 %f24, %f21, %f19;
    mul.f32 %f25, %f24, %f20;
    fma.rn.f32 %f26, %f25, %f22, %f23;
