            grid=(rows, 1, 1),
            block=(1024, 1, 1),
            arguments=[x, output, weight, bias, u64(n), f32(self.ln.eps)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return output

